package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseP1ConcurrencyTest extends MigrationTestSupport {
 static final String SCHEMA="qa_p1_race_"+UUID.randomUUID().toString().replace("-","");
 @DynamicPropertySource static void schema(DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);}
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired ProfessionalScheduling scheduling;@Autowired ProfessionalAuthority authority;@Autowired PlatformTransactionManager manager;@Autowired com.greenocean.backend.account.repository.AccountRepository accounts;
 PhaseIFixtures.Actor pro,staff;UUID qualification;
 @BeforeEach void setup(){PhaseIFixtures.region(db);pro=PhaseIFixtures.member(db,users,tokens);staff=PhaseIFixtures.member(db,users,tokens);qualification=PhasePFixtures.qualified(db,pro.id(),staff.id());}
 @AfterEach void erase(){for(var actor:List.of(pro,staff))new TransactionTemplate(manager).executeWithoutResult(tx->accounts.erase(actor.id()));}
 @AfterAll static void drop(@Autowired JdbcTemplate db){db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 Object result(Supplier<?> run){try{return run.get();}catch(RuntimeException e){return e;}}
 List<Object> race(Supplier<?> a,Supplier<?> b)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var x=pool.submit(()->{start.await();return result(a);});var y=pool.submit(()->{start.await();return result(b);});start.countDown();return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}}
 ProfessionalScheduling.Slot slot(){return new ProfessionalScheduling.Slot(Instant.now().plusSeconds(3600),Instant.now().plusSeconds(5400),"TEXT",0,"Asia/Tehran",true);}
 @Test void twoConnectionsReserveOverlappingProfessionalCapacityOnlyOnce()throws Exception{var a=slot();var b=new ProfessionalScheduling.Slot(a.startsAt().plusSeconds(60),a.endsAt().plusSeconds(60),"VIDEO",0,"Asia/Tehran",true);var results=race(()->scheduling.slot(pro.id(),a),()->scheduling.slot(pro.id(),b));assertThat(results.stream().filter(UUID.class::isInstance).count()).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM professional_availability_slots WHERE professional_user_id=? AND status='AVAILABLE'",Integer.class,pro.id())).isEqualTo(1);}
 @Test void identicalSlotRetryAcrossConnectionsIsIdempotent()throws Exception{var in=slot();var results=race(()->scheduling.slot(pro.id(),in),()->scheduling.slot(pro.id(),in));assertThat(results).allMatch(UUID.class::isInstance);assertThat(results.getFirst()).isEqualTo(results.getLast());}
 @Test void revocationRacingPublicationLeavesNoFutureOffer()throws Exception{var in=slot();race(()->scheduling.slot(pro.id(),in),()->{authority.decide(staff.id(),qualification,new ProfessionalAuthority.Decision(1,"REVOKED","Synthetic independent revocation",null,null,null,null,null,null,null,null,null,null,List.of()));return "revoked";});assertThat(db.queryForObject("SELECT count(*) FROM professional_availability_slots WHERE professional_user_id=? AND status='AVAILABLE'",Integer.class,pro.id())).isZero();assertThat(db.queryForObject("SELECT professional_qualification_live(?)",Boolean.class,pro.id())).isFalse();}
}
